        for rr in rs:
            for i,v in enumerate(right):
                if cb+1+i<w: g[rr][cb+1+i]=v
        # left vertical stripe patterns on the far left repeat along horizontal bar
        rbar=min(rs); cbar=[c for c in range(w) if g[rbar][c]==5]
